class Solution:
    def allCellsDistOrder(self, R, C, r0, c0):
        def append(R, C, r, c, result):
            if 0 <= r < R and 0 <= c < C:
                result.append([r, c])

        result = [[r0, c0]]
        for d in range(1, R+C):
            append(R, C, r0-d, c0, result)
            for x in range(-d+1, d):
                append(R, C, r0+x, c0+abs(x)-d, result)
                append(R, C, r0+x, c0+d-abs(x), result)
            append(R, C, r0+d, c0, result)
        return result

