    def kWeakestRows(self, mat: List[List[int]], k: int) -> List[int]:
        result, lookup = [], set()
        for j in range(len(mat[0])):
            for i in range(len(mat)):
                if mat[i][j] or i in lookup:
                    continue
                lookup.add(i)
                result.append(i)
                if len(result) == k:
                    return result
